package com.securecare.service;
import com.securecare.domain.enums.UserRole;import com.securecare.domain.model.UserDocument;import com.securecare.repository.UserRepository;import com.securecare.security.JwtService;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.Instant;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AuthServiceTest {
 @Test void login_validCredentials_expectedToken(){var users=mock(UserRepository.class);var encoder=mock(PasswordEncoder.class);var jwt=mock(JwtService.class);var audit=mock(AuditService.class);var user=new UserDocument("u1","doctor","hash",UserRole.DOCTOR,"d@example.test",true,Instant.now(),null);when(users.findByUsername("doctor")).thenReturn(Optional.of(user));when(encoder.matches("secret","hash")).thenReturn(true);when(jwt.generate("doctor","DOCTOR","u1")).thenReturn("signed-token");var result=new AuthService(users,encoder,jwt,audit).login("doctor","secret",null);assertEquals("signed-token",result.get("token"));verify(users).save(any(UserDocument.class));}
 @Test void login_wrongPassword_expectedRejected(){var users=mock(UserRepository.class);var encoder=mock(PasswordEncoder.class);var jwt=mock(JwtService.class);var audit=mock(AuditService.class);var user=new UserDocument("u1","doctor","hash",UserRole.DOCTOR,"d@example.test",true,Instant.now(),null);when(users.findByUsername("doctor")).thenReturn(Optional.of(user));when(encoder.matches("wrong","hash")).thenReturn(false);assertThrows(IllegalArgumentException.class,()->new AuthService(users,encoder,jwt,audit).login("doctor","wrong",null));verify(users,never()).save(any());}
 @Test void register_pendingUser_expectedInactiveUntilApproved(){var users=mock(UserRepository.class);var encoder=mock(PasswordEncoder.class);var jwt=mock(JwtService.class);var audit=mock(AuditService.class);when(users.findByUsername("nurse")).thenReturn(Optional.empty());when(encoder.encode("secretpass123")).thenReturn("encoded");when(users.save(any(UserDocument.class))).thenAnswer(invocation->{UserDocument doc=invocation.getArgument(0);return new UserDocument("u2",doc.username(),doc.passwordHash(),doc.role(),doc.email(),doc.active(),doc.createdAt(),doc.lastLoginAt());});var result=new AuthService(users,encoder,jwt,audit).register("nurse","secretpass123","nurse@test.com",UserRole.NURSE);assertFalse((boolean) result.get("active"));assertEquals(UserRole.NURSE,result.get("role"));verify(users).save(any(UserDocument.class));}
}
